                      <div>
                        <span className="text-slate-400">Type:</span>
                        <span className={`ml-1 ${
                          procData.type === 'Proc120s' ? 'text-purple-400' :
                          procData.type === 'Global' ? 'text-green-400' :
                          'text-amber-300'
                        }`}>
                          {procData.type === 'Proc120s' ? '100% (120s)' : procData.type}
